function D([string]$v) {
    return [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($v))
}

function Replace-Exact([string]$Rel,[string]$Old64,[string]$New64) {
    $Path = Join-Path $Repo $Rel
    if (-not (Test-Path $Path)) {
        throw "STOP: missing $Rel"
    }

    $Text = [IO.File]::ReadAllText($Path).Replace("`r`n","`n")
    $Old  = (D $Old64).Replace("`r`n","`n")
    $New  = (D $New64).Replace("`r`n","`n")

    $Count = ([regex]::Matches($Text,[regex]::Escape($Old))).Count
    if ($Count -ne 1) {
        throw "STOP: expected exactly one target in $Rel; found $Count"
    }

    [IO.File]::WriteAllText(
        $Path,
        $Text.Replace($Old,$New),
        (New-Object Text.UTF8Encoding($false))
    )
}

Write-Host "=== PRECHECK ==="
