$ExpectedPaths = @(".github/copilot-instructions.md",".github/instructions/tests.instructions.md","AGENTS.md","docs/agents/handoff.md","docs/agents/task-contract.md","docs/agents/workflow.md","docs/deployment.md","docs/plans/PLAN-template.md","docs/tasks/TASK-template.md","docs/testing.md")
