# Governance contradiction guards.
$Forbidden = @(
    "exceptional broader run",
    "Exceptional broader/full run",
    "Coder run Central Lab",
    "coder run Central Lab",
    "full repository regression was intentionally not run by Coder because"
)

foreach ($Needle in $Forbidden) {
    $Hit = git -C $Repo grep -n -F -- "$Needle" -- AGENTS.md docs .github 2>$null
    if ($LASTEXITCODE -eq 0 -and $Hit) {
        Write-Host $Hit
        throw "STOP: stale/ambiguous governance phrase remains: $Needle"
    }
}

